  Variables (ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
            (F : bvmap 5 word) (fc : bv 32) (m : mem).
  Variables (lo : Z) (d : depot) (inited : bool).
  Variables (TSD CTX TH TOP BOT : Z) (CH : list (Z * Z)).
  Variable (sb : Z).
  Let CHI := icpt_chain (bv_unsigned ra) (bv_unsigned s0) (bv_unsigned sp) TOP CH.
  Let T := utrace 0x90ca0 (bv_unsigned sp) TOP BOT 30 CHI.   (* [comment removed for export] *)
  (* [comment removed for export] *)
  Let W : list ivl := [(lo, bv_unsigned sp); (TH + 3168, TH + 3169); (2424008, 2424008 + 4); (1840192, 1840192 + 0x81030)].
  Let PREPOST := free_pre_post ra sp gp tp a0 s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc m lo TSD CTX TH sb TOP BOT T d.

  Hypothesis LO : ltac2:(zQ "20!mnb!lv9@2$1@1$0?5HCEIL?2lo").  Hypothesis HI : ltac2:(zQ "40!h9!hu3!lv9!in5@2$2@2$1?2lo+ps0@2$3@1$0#k0?2sp").
  Hypothesis SPA : ltac2:(zQ "60!jl5!h9!k1!ms6!mt0!in5@1$3@3$0$2@2$4@2$5@1$1#k0?2sp+h0Z").
  Hypothesis SPT : ltac2:(zQ "60!h9!ms6!hu3!lv9!mgf!in5@1$1@2$3@2$2@2$5@1$0#k0?2sp+h0@2$4+2+if").
  Hypothesis P47 : ltac2:(zQ "40!h9!lvf!mgf!in5@2$1@2$3@1$0#k0?2a0@2$2+2+if").
  Hypothesis TPR : ltac2:(zQ "70!h9!lv9!in5!hs4!mta!ms6!hu3@1$5@2$3@2$1+mqiho8@2$2@1$0#k0?2tp@2$1@2$6@2$2@1$0#k0?2tp+hgg0$4").
  Hypothesis RNG : ltac2:(zQ "b0!hs4!lv9!hu3!mnb!jl5!k1!mta!mu6!ms6!muf!mt0@1$8@2$0@2$1+mqihj0?3TSD@2$0@2$1@2$2?3TSD+8$6@2$0@3$9?5HCEIL?3CTX+q0@2$0@2$1@2$2?3CTX+q0@1$3?5HCEIL@2$0@3$7?5HCEIL?2TH+hgg0@2$0@2$1@2$2?2TH+hgg0@1$3?5HCEIL@3$4$5@2$a?2TH+h0Z").
  Hypothesis PLC : ltac2:(zQ "60!hu3!lv9!mv7!hs4!nje!ms6@1$5@2$3@2$2@2$1@2$0?2TH+hgg0?2sb@2$1@2$0@2$0?2sb$4+hgg0?2TH@2$3@2$2@2$1@2$0?3CTX+q0?2sb@2$1@2$0@2$0?2sb$4+hgg0?3CTX@2$2@2$1@2$0?3CTX+q0?2TH@2$1@2$0?2TH+hgg0?3CTX").
  Hypothesis PLCD : ltac2:(zQ "a1!hu3!lv9!nkc!hs4!nl3!nla!mv7!muf!nje!ms6&@2$0@1$4?1d@2$2+h0+hggg0@1$9@2$3@2$6@2$1@2$0?2TH+hgg0@1$4?1d@2$1~0?2TH@2$3@2$6@2$1@2$0?2TH+hgg0@1$5?1d@2$1@2$0@1$5?1d@2$2+8+ogg0?2TH@2$3@2$6@2$1@2$0@2$0?2sb$8+hgg0@1$4?1d@2$1~0?2sb@2$3@2$6@2$1@2$0@2$0?2sb$8+hgg0@1$5?1d@2$1@2$0@1$5?1d@2$2+8+ogg0?2sb@2$3@2$6@2$1@2$0?3CTX+q0@1$4?1d@2$1~0?3CTX@2$3@2$6@2$1@2$0?3CTX+q0@1$5?1d@2$1@2$0@1$5?1d@2$2+8+ogg0?3CTX@2$3@3$7?5HCEIL@1$4?1d@2$2+h0+hggg0@3$7?5HCEIL@1$5?1d@2$2+8+ogg0").
  Let PLACED : Prop := ((TH + 4096 <= sb \/ sb + kSpaceSize + 4096 <= TH) /\ (CTX + 160 <= sb \/ sb + kSpaceSize + 4096 <= CTX)
